parameters.jsCode:
// Collect all tool IDs and prepare assistant update
const items = $input.all();
const toolIds = [];

// Extract tool IDs from responses
for (let i = 2; i < items.length; i++) {
  const item = items[i];
  if (item.json && item.json.id) {
    toolIds.push(item.json.id);
  }
}

const assistantId = items[1].json?.id;
const setupData = items[0].json;

console.log('Collected tool IDs:', toolIds);
console.log('Assistant ID:', assistantId);

return [{
  json: {
    assistant_id: assistantId,
    tool_ids: toolIds,
    server_url: setupData['Server URL'],
    test_email: setupData['Test Contact Email'],
    company_name: setupData['Company Name'],
    tools_created: {
      hubspot: toolIds[0],
      email: toolIds[1],
      web_search: toolIds[2],
      database: toolIds[3],
      calendar: toolIds[4]
    }
  }
}];

