// Generate comprehensive test summary
const items = $input.all();
const config = items[0].json;
const phoneResponse = items[1].json;

const testSummary = {
  setup_completed: true,
  assistant_id: config.assistant_id,
  phone_number: phoneResponse?.number || 'Pending activation',
  test_configuration: {
    server_url: config.server_url,
    test_email: config.test_email,
    company_name: config.company_name
  },
  integration_tools: [
    {
      name: "HubSpot CRM",
      function: "save_customer_to_hubspot",
      endpoint: `${config.server_url}/integrations/hubspot/webhook`,
      test_command: "Save my contact info to HubSpot"
    },
    {
      name: "Email Notifications",
      function: "send_notification_email",
      endpoint: `${config.server_url}/integrations/resend/webhook`,
      test_command: "Send an email to ailabsafrica@gmail.com about this call"
    },
    {
      name: "Web Search (Tavily)",
      function: "search_web_information",
      endpoint: `${config.server_url}/integrations/tavily/webhook`,
      test_command: "Search for information about AI Labs Africa"
    },
    {
      name: "Database Storage (Supabase)",
      function: "save_call_data",
      endpoint: `${config.server_url}/integrations/supabase/webhook`,
      test_command: "Save this call information to the database"
    },
    {
      name: "Calendar Scheduling (Calendly)",
      function: "schedule_appointment",
      endpoint: `${config.server_url}/integrations/calendly/webhook`,
      test_command: "Schedule a 30-minute meeting for tomorrow at 2 PM"
    }
  ],
  test_script: {
    introduction: "Hi, I'd like to test all your integration capabilities",
