      "Please save my contact info: John Doe, john@example.com, +1234567890, ABC Company",
      "Search for information about AI Labs Africa on the web",
      "Send an email to ailabsafrica@gmail.com with a summary of this test call",
      "Save this call data to the database",
      "Schedule a 30-minute consultation meeting for tomorrow at 2 PM"
    ],
    expected_outcomes: [
      "Contact saved to HubSpot",
      "Web search results provided",
      "Email sent successfully",
      "Call data saved to Supabase",
      "Calendar appointment scheduled"
    ]
  },
  webhook_endpoints: {
    main_webhook: `${config.server_url}/integrations/vapi-webhook`,
    hubspot: `${config.server_url}/integrations/hubspot/webhook`,
    email: `${config.server_url}/integrations/resend/webhook`,
    search: `${config.server_url}/integrations/tavily/webhook`,
    database: `${config.server_url}/integrations/supabase/webhook`,
    calendar: `${config.server_url}/integrations/calendly/webhook`
  }
};

console.log('Integration Test Setup Complete:', JSON.stringify(testSummary, null, 2));

return [{ json: testSummary }];
